            const SizedBox(height: 8),
            SvgPicture.string(
              '''<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
                <circle cx="50" cy="50" r="40" fill="#2196F3"/>
                <text x="50" y="55" text-anchor="middle" fill="white" font-size="20">SVG</text>
