                SvgPicture.asset('assets/icons/flutter_logo.svg', width: 30),
                const SizedBox(width: 8),
                SvgPicture.asset('assets/icons/flutter_logo.svg', width: 50),
                const SizedBox(width: 8),
                SvgPicture.asset('assets/icons/flutter_logo.svg', width: 80),
              ],
            ),

            const SizedBox(height: 24),

