        Text(label, style: const TextStyle(fontSize: 12)),
      ],
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_svg/flutter_svg.dart';

class SvgColorExample extends StatefulWidget {
  const SvgColorExample({super.key});

  @override
  State<SvgColorExample> createState() => _SvgColorExampleState();
}

class _SvgColorExampleState extends State<SvgColorExample> {
  Color _selectedColor = Colors.blue;

  final List<Color> _colors = [
    Colors.blue,
    Colors.red,
    Colors.green,
    Colors.orange,
    Colors.purple,
    Colors.teal,
  ];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('SVG 색상 변경')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            // 색상이 변경된 SVG
            SvgPicture.asset(
              'assets/icons/flutter_logo.svg',
              width: 150,
              height: 150,
              colorFilter: ColorFilter.mode(
                _selectedColor,
                BlendMode.srcIn,  // 가장 많이 사용되는 모드
              ),
            ),

            const SizedBox(height: 32),

            // 색상 선택 버튼들
            const Text('색상 선택:', style: TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(height: 16),
            Wrap(
              spacing: 12,
              children: _colors.map((color) {
                final isSelected = color == _selectedColor;
                return GestureDetector(
                  onTap: () => setState(() => _selectedColor = color),
                  child: Container(
                    width: 48,
                    height: 48,
                    decoration: BoxDecoration(
                      color: color,
                      shape: BoxShape.circle,
                      border: Border.all(
                        color: isSelected ? Colors.black : Colors.transparent,
                        width: 3,
                      ),
                    ),
                    child: isSelected
                        ? const Icon(Icons.check, color: Colors.white)
                        : null,
                  ),
                );
              }).toList(),
            ),

            const SizedBox(height: 32),
            const Divider(),
            const SizedBox(height: 16),

            // 다크모드 대응 예제
            const Text('다크모드 대응', style: TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(height: 16),
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                _buildThemeIcon(false),
                _buildThemeIcon(true),
              ],
            ),

            const SizedBox(height: 32),
            const Divider(),
            const SizedBox(height: 16),

            // 선택 상태 아이콘 예제
            const Text('선택 상태 표시', style: TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(height: 16),
            _buildSelectableIcons(),
          ],
        ),
      ),
    );
  }

  Widget _buildThemeIcon(bool isDark) {
    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: isDark ? Colors.grey.shade900 : Colors.grey.shade100,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Column(
        children: [
          SvgPicture.asset(
            'assets/icons/flutter_logo.svg',
            width: 60,
            colorFilter: ColorFilter.mode(
              isDark ? Colors.white : Colors.black,
              BlendMode.srcIn,
            ),
          ),
          const SizedBox(height: 8),
          Text(
            isDark ? 'Dark' : 'Light',
            style: TextStyle(
              color: isDark ? Colors.white : Colors.black,
            ),
          ),
        ],
      ),
    );
  }

  int _selectedIndex = 0;

  Widget _buildSelectableIcons() {
    final icons = ['home', 'search', 'favorite', 'settings'];

    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceEvenly,
      children: List.generate(icons.length, (index) {
        final isSelected = index == _selectedIndex;
        return GestureDetector(
          onTap: () => setState(() => _selectedIndex = index),
          child: Column(
            children: [
              SvgPicture.asset(
                'assets/icons/${icons[index]}.svg',
                width: 32,
                colorFilter: ColorFilter.mode(
                  isSelected ? Colors.blue : Colors.grey,
                  BlendMode.srcIn,
                ),
              ),
              const SizedBox(height: 4),
              Text(
                icons[index],
                style: TextStyle(
                  color: isSelected ? Colors.blue : Colors.grey,
                  fontSize: 12,
                ),
              ),
            ],
          ),
        );
      }),
    );
  }
}

