/// 재사용 가능한 SVG 아이콘 위젯
class SvgIcon extends StatelessWidget {
  final String assetPath;
  final double? size;
  final Color? color;
  final BoxFit fit;

  const SvgIcon(
    this.assetPath, {
    super.key,
    this.size,
    this.color,
    this.fit = BoxFit.contain,
  });

  @override
  Widget build(BuildContext context) {
    // 기본 색상: 테마의 아이콘 색상
    final effectiveColor = color ?? IconTheme.of(context).color;

    return SvgPicture.asset(
      assetPath,
      width: size,
      height: size,
      fit: fit,
      colorFilter: effectiveColor != null
          ? ColorFilter.mode(effectiveColor, BlendMode.srcIn)
          : null,
    );
  }
}

/// 테마 인식 SVG 아이콘 (다크모드 자동 대응)
class ThemeSvgIcon extends StatelessWidget {
  final String assetPath;
  final double? size;
  final Color? lightColor;
  final Color? darkColor;

  const ThemeSvgIcon(
    this.assetPath, {
    super.key,
    this.size,
    this.lightColor,
    this.darkColor,
  });

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final color = isDark 
        ? (darkColor ?? Colors.white)
        : (lightColor ?? Colors.black);

    return SvgPicture.asset(
      assetPath,
      width: size,
      height: size,
      colorFilter: ColorFilter.mode(color, BlendMode.srcIn),
    );
  }
}

/// 아이콘 버튼 위젯
class SvgIconButton extends StatelessWidget {
  final String assetPath;
  final double size;
  final Color? color;
  final VoidCallback onPressed;
  final String? tooltip;

  const SvgIconButton({
    super.key,
    required this.assetPath,
    this.size = 24,
    this.color,
    required this.onPressed,
    this.tooltip,
  });

  @override
  Widget build(BuildContext context) {
    final button = IconButton(
      onPressed: onPressed,
      icon: SvgIcon(assetPath, size: size, color: color),
    );

    if (tooltip != null) {
      return Tooltip(
        message: tooltip!,
        child: button,
      );
    }

    return button;
  }
}

