/// SVG 프리캐싱 서비스
class SvgCacheService {
  static final SvgCacheService _instance = SvgCacheService._internal();
  factory SvgCacheService() => _instance;
  SvgCacheService._internal();

  /// 자주 사용하는 SVG 프리로드
  Future<void> preloadSvgs(List<String> assetPaths) async {
    for (final path in assetPaths) {
      // SVG 로더를 사용하여 프리캐시
      final loader = SvgAssetLoader(path);
      await svg.cache.putIfAbsent(
        loader.cacheKey(null),
        () => loader.loadBytes(null),
      );
    }
  }

  /// 캐시 클리어
  void clearCache() {
    svg.cache.clear();
  }
}

/// 최적화된 SVG 이미지 위젯
class OptimizedSvgPicture extends StatelessWidget {
  final String assetPath;
  final double? width;
  final double? height;
  final Color? color;
  final BoxFit fit;

  const OptimizedSvgPicture({
    super.key,
    required this.assetPath,
    this.width,
    this.height,
    this.color,
    this.fit = BoxFit.contain,
  });

  @override
  Widget build(BuildContext context) {
    return SvgPicture.asset(
      assetPath,
      width: width,
      height: height,
      fit: fit,
      colorFilter: color != null
          ? ColorFilter.mode(color!, BlendMode.srcIn)
          : null,
      // 성능 최적화 옵션
      placeholderBuilder: (context) => SizedBox(
        width: width,
        height: height,
      ),
    );
  }
}

/// 앱 시작 시 SVG 프리로드 예제
class SvgOptimizationExample extends StatefulWidget {
  const SvgOptimizationExample({super.key});

  @override
  State<SvgOptimizationExample> createState() => _SvgOptimizationExampleState();
}

class _SvgOptimizationExampleState extends State<SvgOptimizationExample> {
  bool _isLoading = true;

  @override
  void initState() {
    super.initState();
    _preloadSvgs();
  }

  Future<void> _preloadSvgs() async {
    // 자주 사용하는 SVG 미리 로드
    await SvgCacheService().preloadSvgs([
      'assets/icons/home.svg',
      'assets/icons/search.svg',
      'assets/icons/favorite.svg',
      'assets/icons/profile.svg',
      'assets/icons/logo.svg',
    ]);

    if (mounted) {
      setState(() {
        _isLoading = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_isLoading) {
      return const Scaffold(
        body: Center(child: CircularProgressIndicator()),
      );
    }

    return Scaffold(
      appBar: AppBar(title: const Text('최적화된 SVG')),
      body: ListView(
        padding: const EdgeInsets.all(16),
        children: [
          const Text('프리로드된 SVG는 즉시 표시됩니다', 
              style: TextStyle(fontWeight: FontWeight.bold)),
          const SizedBox(height: 16),

          // 그리드로 많은 아이콘 표시
          GridView.builder(
            shrinkWrap: true,
            physics: const NeverScrollableScrollPhysics(),
            gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: 4,
              mainAxisSpacing: 16,
              crossAxisSpacing: 16,
            ),
            itemCount: 20,
            itemBuilder: (context, index) {
              final icons = ['home', 'search', 'favorite', 'profile', 'logo'];
              final iconName = icons[index % icons.length];
              return Column(
                children: [
                  OptimizedSvgPicture(
                    assetPath: 'assets/icons/$iconName.svg',
                    width: 40,
                    height: 40,
                    color: Colors.primaries[index % Colors.primaries.length],
                  ),
                  const SizedBox(height: 4),
                  Text(iconName, style: const TextStyle(fontSize: 10)),
                ],
              );
            },
          ),

          const SizedBox(height: 32),

          ElevatedButton(
            onPressed: () {
              SvgCacheService().clearCache();
              ScaffoldMessenger.of(context).showSnackBar(
                const SnackBar(content: Text('SVG 캐시가 삭제되었습니다')),
              );
            },
            child: const Text('캐시 클리어'),
          ),
        ],
      ),
    );
  }
}

